// indexPerFile processes files one at a time (original behavior)
// fellBack holds the files an earlier run recorded as fallen back.
func (m *IndexManager) indexPerFile(ctx context.Context, files []string, opts IndexOptions, fellBack map[string]FallbackReason, result *IndexResult) (*IndexResult, error) {
	totalFiles := len(files)

	for i, file := range files {
		select {
		case <-ctx.Done():
			return result, ctx.Err()
		default:
		}

		// Check if file is already indexed and unchanged (for resume capability)
		if !opts.Force {
			needsIndex, err := m.fileNeedsUpdate(ctx, file)
			if err != nil {
				// An unreadable file is not indexed; counting it unchanged would hide that.
				result.Errors = append(result.Errors, fmt.Sprintf("%s: %v", file, err))
				result.FilesSkipped++
				if opts.OnProgress != nil {
					opts.OnProgress(ProgressEvent{
						Current:     i + 1,
						Total:       totalFiles,
						FilePath:    file,
						ChunksTotal: result.ChunksCreated,
						Skipped:     true,
					})
				}
				continue
			}
			if !needsIndex {
				result.FilesUnchanged++
				if reason, ok := fellBack[file]; ok {
					result.addFallback(file, reason)
				}
				// Report progress for skipped file
				if opts.OnProgress != nil {
					opts.OnProgress(ProgressEvent{
						Current:     i + 1,
						Total:       totalFiles,
						FilePath:    file,
						ChunksTotal: result.ChunksCreated,
						Skipped:     true,
					})
				}
				continue
			}
		}

		// Process the file
		processErr := m.processFile(ctx, file, result, opts.BatchSize, opts.Parallel, opts.Domain)
		if processErr != nil {
			result.Errors = append(result.Errors, fmt.Sprintf("%s: %v", file, processErr))
			result.FilesSkipped++
		} else {
			result.FilesProcessed++
		}

		// Report progress
		if opts.OnProgress != nil {
			opts.OnProgress(ProgressEvent{
				Current:     i + 1,
				Total:       totalFiles,
				FilePath:    file,
				ChunksTotal: result.ChunksCreated,
				Skipped:     false,
			})
		}
	}

	return result, nil
}

// IndexLock provides cross-process file locking for index operations.
// Prevents concurrent index/index-update processes from corrupting shared state.
type IndexLock struct {
	flock *flock.Flock
	path  string
}

